doc = json.load(open(PATH, encoding="utf8"))
asset = doc["asset"]
for scale, text in STRUCTURE.items():
    decisions = asset["volumes"][scale]["decisions"]
    index = next(i for i, d in enumerate(decisions) if d["en"].startswith("Structure 1:"))
    decisions[index] = {"en": text["en"] + BAG["en"], "de": text["de"] + BAG["de"]}
asset["volumes"]["100"]["decisions"][0] = BODY_100
if not any(d["en"].startswith("Rig and cut") for d in asset["volumes"]["50"]["decisions"]):
    asset["volumes"]["50"]["decisions"].insert(1, RIG_50)
for language in ("en", "de"):
    if NOTE[language] not in asset["provenance"]["notes"][language]:
        asset["provenance"]["notes"][language] += NOTE[language]
open(PATH, "w", encoding="utf8").write(json.dumps(doc, ensure_ascii=False) + "\n")
